workedExamples.code:
#include <iostream>
int main() {
    int age;
    if (!(std::cin >> age)) { std::cout << "invalid\n"; return 0; }
    if (age >= 0 && age <= 120) std::cout << "valid\n";
    else std::cout << "invalid\n";
}

#include <iostream>
int main() {
    int seconds;
    if (!(std::cin >> seconds)) { std::cout << "invalid\n"; return 0; }
    if (seconds < 0) { std::cout << "invalid\n"; return 0; }
    std::cout << seconds / 60 << ' ' << seconds % 60 << '\n';
}

